#include "calc_cycle.h"

#include <assert.h>
#include <fcntl.h>
#include <stdio.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/times.h>
#include <time.h>
#include <unistd.h>

#undef AT_FDCWD
#define AT_FDCWD -100
#undef O_CREAT
#define O_CREAT 64
uint64_t cycle;
uint64_t cycleStart;

extern int sys_write(int, char*, int);

#define TEST_FILE_TEXT "hello from syscall test\n"
#define TEST_RENAME_TEXT "rename test file\n"

static void create_file(const char *name, const char *content)
{
  int fd = open(name, O_CREAT | O_TRUNC | O_RDWR, 0644);
  assert(fd != -1);

  if (content != NULL) {
    ssize_t len = 0;
    while (content[len] != '\0') {
      len++;
    }
    assert(write(fd, content, len) == len);
  }

  close(fd);
}

#define TEST_SYSCALL(name, call) do { \
  StartCalc; \
  call; \
  EndCalc; \
  printf(name " cycles: %lld\n", cycle); \
} while(0)

int main(int argc, char **argv)
{
  printf("========TEST START========\n");

  int ret, fd;
  struct stat st;
  struct timeval tv;
  struct tms t;
  clock_t cl;
  char buf[100];

  // Prepare the files this test expects to find.
  create_file("test.txt", TEST_FILE_TEXT);
  create_file("test2.txt", "");
  create_file("test_rename.txt", TEST_RENAME_TEXT);

  // Test printf (using direct syscall interface)
  // The 1st call to functions in stdio.h will trigger initialization overhead,
  // including _fstat and _isatty calls and malloc buffer.
  TEST_SYSCALL("printf", printf("1st Hello from direct syscall interface!\n"));

  // The 2nd call should be more representative
  TEST_SYSCALL("printf", printf("2nd Hello from direct syscall interface!\n"));

  // Test access
  access("test.txt", X_OK);
  TEST_SYSCALL("access", ret = access("test.txt", X_OK));
  assert(ret == -1);

  // Test open
  open("test.txt", O_RDWR, 0);
  TEST_SYSCALL("open", fd = open("test.txt", O_RDWR, 0));
  assert(fd != -1);

  // Test lseek
  lseek(fd, 0, SEEK_END);
  TEST_SYSCALL("lseek", ret = lseek(fd, 0, SEEK_END));
  assert(ret != 0);

  // Test fstat
  fstat(fd, &st);
  TEST_SYSCALL("fstat", ret = fstat(fd, &st));
  assert(ret == 0);
  assert(st.st_mode == 0100644);
  // printf("mode:%o\n", st.st_mode);

  int fd2 = open("test2.txt", O_RDWR);
  // Test close
  close(fd);
  TEST_SYSCALL("close", ret = close(fd2));
  assert(ret == 0);

  // Test gettimeofday
  gettimeofday(&tv, NULL);
  TEST_SYSCALL("gettimeofday", ret = gettimeofday(&tv, NULL));
  assert(ret == 0);
  printf("gettimeofday:%ld\n", tv.tv_sec);

  // Test isatty
  isatty(0);
  TEST_SYSCALL("isatty", ret = isatty(0));
  assert(ret == 1);

  // Test faccessat
  faccessat(AT_FDCWD, "test.txt", X_OK, 0);
  TEST_SYSCALL("faccessat", ret = faccessat(AT_FDCWD, "test.txt", X_OK, 0));
  assert(ret == -1);

  // Test link
  link("test.txt", "new_test.txt");
  TEST_SYSCALL("link", ret = link("test.txt", "new_test2.txt"));
  assert(ret == 0);

  // check if file exist
  fd = open("new_test.txt", O_RDWR, 0);
  assert(fd != -1);

  // Test unlink
  unlink("new_test.txt");
  TEST_SYSCALL("unlink", ret = unlink("new_test2.txt"));
  assert(ret == 0);

  fd = open("new_test.txt", O_RDWR, 0);
  assert(fd == -1);
  fd = open("new_test2.txt", O_RDWR, 0);
  assert(fd == -1);

  // test lstat (need extra DEFINE symbol to enable)
  // ret = lstat("test.txt", &st);
  // assert(ret == 0);
  // printf("mode:%o\n", st.st_mode);

  // Test openat
  openat(AT_FDCWD, "test.txt", O_RDWR);
  TEST_SYSCALL("openat", fd = openat(AT_FDCWD, "test.txt", O_RDWR));
  assert(fd != -1);

  // Test read
  read(fd, buf, 10);
  TEST_SYSCALL("read", ret = read(fd, buf, 10));
  if (ret >= 0 && ret < (int)sizeof(buf)) {
    buf[ret] = '\0';
  }
  printf("%s\n", buf);

  // Test rename
  rename("test_rename.txt", "rename_temp.txt");
  TEST_SYSCALL("rename", ret = rename("rename_temp.txt", "rename.txt"));
  assert(ret == 0);
  fd = open("rename.txt", O_RDWR, 0);
  rename("rename.txt", "test_rename.txt");
  // Check if file exists
  assert(fd != -1);
  close(fd);

  // Test stat
  stat("test_rename.txt", &st);
  TEST_SYSCALL("stat", ret = stat("test_rename.txt", &st));
  assert(ret == 0);
  assert(st.st_mode == 0100644);
  // printf("mode:%o\n", st.st_mode);

  // Test times (currently not correctly implemented)
  times(&t);
  TEST_SYSCALL("times", cl = times(&t));
  printf("clock times: %ld\n", cl);

  // Test write
  fd = open("test_rename.txt", O_RDWR, 0);
  write(fd, "write test", 11);
  TEST_SYSCALL("write", ret = write(fd, "write test", 11));
  close(fd);

  // Test create file
  fd = open("test_create1.txt", O_CREAT, 0644);
  close(fd);
  TEST_SYSCALL("open_create", fd = open("test_create2.txt", O_CREAT, 0644));
  assert(fd != -1);
  close(fd);


  // Test remove
  remove("test_create1.txt");
  TEST_SYSCALL("remove", ret = remove("test_create2.txt"));
  assert(ret == 0);

  unlink("test.txt");
  unlink("test2.txt");
  unlink("test_rename.txt");

  printf("========TEST COMPLETE========\n");

  return 0;
}

